// The asset rating pass of 2026-10-17, rebuilt and checked.
//
// The operator: "rate the quality of each asset being generated by each
// feature after testing for any brand". Four brands (a coffee store with a
// catalogue, an app, a news publisher, a bare name) went through Smart Brain
// on the template path and with a model answering, and the trigger mailer;
// every asset was rendered in Chromium. What the pass found, each fixed:
//   1. ONE invented line in a model answer ("Award-winning service", a
//      landing bullet) made the brand guard discard the WHOLE answer - mailer,
//      landing page and every ad fell to the template. The copy is now held to
//      the brand's own words BEFORE the guard, so only that line goes.
//   2. A model's Google RSA shipped its own 3 headlines and 2 descriptions;
//      the template path already offers up to 15 / 4 from the brand's own
//      lines. The model's lines lead, the brand's own follow, none over limit.
//   3. The mailer said a claim in the body and again under "What you get".
//   4. Product cards in the mailer were unequal when one name wrapped; the
//      landing page's "Also from" photo card was shorter than an initial tile.
//   5. The landing hero's eyebrow sat at the left edge of a centred hero.
//
// Executed: the shipped buildCampaign with a scripted model, assets rendered
// in Chromium.
//
// Run: npx playwright test tests/asset-rating-pass.spec.js --project=desktop-1280
const { test, expect } = require('@playwright/test');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const LLM = require.resolve(path.join(ROOT, 'api', '_shared', 'llm.js'));
const PLAN = require.resolve(path.join(ROOT, 'api', '_shared', 'smart-brain-plan.js'));
const KEYS = ['SUPABASE_URL', 'NEXT_PUBLIC_SUPABASE_URL', 'SUPABASE_SERVICE_ROLE_KEY', 'SUPABASE_SERVICE_KEY', 'FREE_GENERATION'];
const IMG = (n) => `https://palmgrove.example/cdn/${n}.jpg`;

const COFFEE = {
  id: 'device:palmgrove', slug: 'palmgrove', name: 'Palmgrove Coffee', website: 'https://palmgrove.example', industry: 'Single-origin coffee roaster and store',
  tagline: 'Roasted on Tuesdays, at your door by Friday',
  palette: { primary: '#5A2E1B', accent: '#E0A43B', ink: '#2A1D16', surface: '#FFF9F1' },
  regions: [{ code: 'IN', currency: 'INR', store_url: 'https://palmgrove.example', home: true }],
  claims: ['Roasted in small batches every Tuesday', 'Shipped within three days of roasting'],
  legal_entity: 'Palmgrove Coffee Pvt Ltd, Coorg 571201, India',
};
const NEWS = {
  id: 'device:gazette', slug: 'gazette', name: 'Ledgerline Gazette', website: 'https://ledgerline.example', industry: 'news publishing',
  tagline: 'Pune news, checked twice by the desk',
  palette: { primary: '#7B2D5E', accent: '#C8A13B', ink: '#2A1F33', surface: '#FBF7EF' },
  regions: [{ code: 'IN', currency: 'INR', home: true }], claims: ['Reporters in all 14 Pune wards'],
  offerings: [{ kind: 'subscription', name: 'Morning Ledger', url: 'https://ledgerline.example/ledger' }],
  legal_entity: 'Ledgerline Media LLP, Pune, India',
};
const slot = (b, x) => Object.assign({
  id: 'rating-' + b.slug, date: '2026-10-20', market: 'IN', objective: 'reactivation', brand: b,
  cohort: { name: 'At Risk', size: 1200, rules: ['r'] }, channels: ['email', 'meta', 'google', 'tiktok', 'landing_page'],
  confidence: 0.6, offer: { depth: 'none', pct: 0 },
}, x || {});
const PRODUCTS = {
  heroProduct: { sku: 'P1', title: 'Palmgrove Estate Medium Roast', handle: 'estate-medium', category: 'Coffee', image: IMG('estate'), price: 650 },
  supportingProducts: [
    { sku: 'P2', title: 'Palmgrove Dark Roast', handle: 'dark', category: 'Coffee', image: IMG('dark'), price: 700 },
    { sku: 'P3', title: 'Palmgrove Filter Blend', handle: 'filter', category: 'Coffee', price: 520 },
  ],
};
// A realistic answer: on topic, the brand's own claims, and one line of the
// fluff a model adds ("Award-winning service").
const modelCopy = (b, hero) => ({
  email: {
    subject: `${b.name}: it has been a while`, preheader: `Here is what is new at ${b.name}`, hook: 'h', hero_headline: `Back to ${hero || b.name}`,
    intro_paragraph: `We noticed you have not visited ${b.name} lately. ${b.claims[0]}.`, body_paragraph: b.claims[1] ? `${b.claims[1]}.` : '',
    benefits: b.claims.slice(), rating: null, reviews: [], badges: [], guarantee: '', ps: 'See you soon.', faq: [], cta: 'Come back', image_brief: 'x',
  },
  landing: { hero_headline: `Back to ${hero || b.name}`, hero_sub: `${b.tagline}.`, why_title: `Why ${b.name}`, why_bullets: b.claims.concat(['Award-winning service']), proof_quote: '', proof_author: '', faq: [], cta: 'Come back', image_brief: 'y' },
  ads: {
    meta: { primary_text: `${b.tagline}. ${b.claims[0]}.`, headline: `Back to ${b.name}`, description: b.name, image_brief: 'z' },
    google: { headlines: [b.name, 'Come back today', b.claims[0].slice(0, 30)], descriptions: [`${b.tagline}.`, `${b.claims[0]}.`], image_brief: 'w' },
    tiktok: { script: 's', caption: b.tagline, image_brief: 'v' },
  },
});

async function build(entry) {
  const saved = Object.fromEntries(KEYS.map((k) => [k, process.env[k]]));
  for (const k of KEYS) delete process.env[k];
  process.env.FREE_GENERATION = 'off';
  const realLlm = require.cache[LLM]; const realPlan = require.cache[PLAN];
  try {
    const real = require(LLM);
    const hero = entry.heroProduct && entry.heroProduct.title;
    const stub = async (o) => ({ text: JSON.stringify(/strategy/.test(String(o.stage || '')) ? { angle: 'a', framework: 'PAS', hook_thesis: 'x', target_emotion: 'calm', proof_points: [], differentiator: 'x', dos: [], donts: [] } : modelCopy(entry.brand, hero)), provider: 'scripted', model: 'scripted' });
    Object.assign(stub, real);
    require.cache[LLM] = { id: LLM, filename: LLM, loaded: true, exports: stub };
    delete require.cache[PLAN];
    const { smartConfig } = require(path.join(ROOT, 'lib', 'smart-brain', 'services.js'));
    return await require(PLAN).buildCampaign(JSON.parse(JSON.stringify(entry)), smartConfig({}), { noLLM: false, withCreatives: false });
  } finally {
    require.cache[LLM] = realLlm; if (realPlan) require.cache[PLAN] = realPlan; else delete require.cache[PLAN];
    for (const [k, v] of Object.entries(saved)) { if (v === undefined) delete process.env[k]; else process.env[k] = v; }
  }
}
const textOf = (html) => String(html || '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
const PHOTO = '<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600"><rect width="800" height="600" fill="#caa"/></svg>';

let C = null; let N = null;
test.beforeAll(async () => { C = await build(slot(COFFEE, PRODUCTS)); N = await build(slot(NEWS)); });

test('one invented line costs that line, not the whole model answer', () => {
  for (const c of [C, N]) {
    expect(c.copywriter && c.copywriter.provider, JSON.stringify(c.brand_guard || null)).toBe('scripted');
    expect(c.assets.email.subject).toMatch(/it has been a while/);
    const dropped = (c.copy_grounding && c.copy_grounding.dropped) || [];
    expect(dropped.map((d) => d.text)).toContain('Award-winning service');
    expect(dropped.length, 'each dropped line is recorded once, not once per direction').toBe(new Set(dropped.map((d) => d.field + '|' + d.text)).size);
    for (const lp of c.assets.landing_pages) expect(textOf(lp.html)).not.toMatch(/award-winning/i);
  }
});

test('a model\'s Google RSA is topped up with the brand\'s own lines, none over Google\'s limits', () => {
  for (const c of [C, N]) {
    for (const ad of c.assets.ads.filter((a) => a.platform === 'google')) {
      expect(ad.headlines[1], 'the model\'s own lines lead').toBe('Come back today');
      expect(ad.headlines.length, ad.headlines.join(' | ')).toBeGreaterThanOrEqual(5);
      expect(ad.headlines.length).toBeLessThanOrEqual(15);
      expect(ad.descriptions.length).toBeGreaterThanOrEqual(3);
      expect(ad.descriptions.length).toBeLessThanOrEqual(4);
      for (const h of ad.headlines) expect(h.length, h).toBeLessThanOrEqual(30);
      for (const d of ad.descriptions) expect(d.length, d).toBeLessThanOrEqual(90);
      const low = ad.headlines.map((h) => h.toLowerCase());
      expect(new Set(low).size, 'no headline twice').toBe(low.length);
    }
  }
});

test('the mailer never says the same claim in its body and again under "What you get"', () => {
  for (const v of C.assets.email.variants.concat({ name: 'main', html: C.assets.email.html })) {
    const t = textOf(v.html);
    for (const claim of COFFEE.claims) {
      const n = t.split(claim).length - 1;
      expect(n, `${v.name || v.label}: "${claim}"`).toBeLessThanOrEqual(1);
    }
  }
});

test('cards in a row are the same size in the mailer and on the landing page; the hero eyebrow is centred', async ({ page }) => {
  await page.route(/^https?:\/\//, (r) => r.fulfill({ contentType: 'image/svg+xml', body: PHOTO }));
  const visual = C.assets.email.variants.find((v) => /Visual/.test(v.name || v.label || ''));
  await page.setViewportSize({ width: 700, height: 1000 });
  await page.setContent(visual.html, { waitUntil: 'load' });
  // The showcase grid (2026-10-18): the products beside the hero, two to a
  // row, each card marked [data-mail-card]; the hero product has the picture
  // above and is not printed again.
  const mailCards = await page.evaluate(() => [...document.querySelectorAll('[data-mail-card]')].map((d) => Math.round(d.getBoundingClientRect().height)));
  expect(mailCards.length).toBeGreaterThanOrEqual(2);
  expect(new Set(mailCards).size, `mail card heights ${mailCards}`).toBe(1);

  const lp = C.assets.landing_pages[0].html;
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.setContent(lp, { waitUntil: 'load' });
  // A grid row stretches the cards themselves, so the picture area is what
  // read unequal: a photo and an initial tile must be the same size.
  const lpCards = await page.evaluate(() => [...document.querySelectorAll('.others .other')].map((d) => { const m = d.querySelector('img, .ph'); return m ? Math.round(m.getBoundingClientRect().height) : -1; }));
  expect(lpCards.length).toBe(2);
  expect(new Set(lpCards).size, `landing card picture heights ${lpCards}`).toBe(1);

  await page.setContent(N.assets.landing_pages[0].html, { waitUntil: 'load' });
  const off = await page.evaluate(() => {
    const centre = (el) => { const r = el.getBoundingClientRect(); return r.left + r.width / 2; };
    const eb = document.querySelector('.hero .eyebrow'); const h1 = document.querySelector('.hero h1');
    const range = document.createRange(); range.selectNodeContents(eb); const r = range.getBoundingClientRect();
    return Math.abs((r.left + r.width / 2) - centre(h1));
  });
  expect(off, 'the eyebrow text is centred over the headline').toBeLessThan(4);
  const card = await page.evaluate(() => { const li = document.querySelector('.offers li'); const s = getComputedStyle(li); return { bg: s.backgroundColor, page: getComputedStyle(document.body).backgroundColor, border: s.borderTopColor }; });
  expect(card.bg === card.page && card.border === card.page, `the offering card stands off the page ${JSON.stringify(card)}`).toBe(false);
});
